/** The two sentences the Tests paragraph can carry about CI, one of which it must: the legs skip there (no engine installed
 *  before the job's Test step), or they run there (an install of Firefox and WebKit before it). The pin reads the sentence and
 *  the job together, so a CI remedy is taken by rewording the sentence in the same commit, and the pin's message says so. */
const CI_SKIP = "In CI, the job whose step runs npm test has no Playwright browser install and no restore of Playwright's browser cache before that step";
const CI_RUN = "In CI, the job whose step runs npm test installs Firefox and WebKit through Playwright before that step, so the legs run there";
/** The jobs under `jobs:` in a workflow file, each block from its two-space key to the next two-space key or the end. */
function jobBlocks(ci) {
  const jobsAt = ci.indexOf('\njobs:\n');
  assert.ok(jobsAt >= 0, 'the workflow has a jobs: map');
  const jobs = ci.slice(jobsAt);
  const keys = [...jobs.matchAll(/\n {2}([A-Za-z_][\w-]*):\n/g)];
  assert.ok(keys.length >= 1, 'the jobs: map has a job');
  return keys.map((m, i) => ({ key: m[1], block: jobs.slice(m.index + 1, i + 1 < keys.length ? keys[i + 1].index + 1 : jobs.length) }));
}
const NPM_TEST = '\n        run: npm test\n';
/** The job that runs npm test, found by that step and not by its key: the property the Tests paragraph states is about the job
 *  whose Test step runs the legs, whatever the job is called (the round-2 review of the fork PR renamed the key in a scratch and
 *  the by-name lookup turned red with the property unchanged, 2026-09-20). Nothing here reads the job's key: the plan's two CI
 *  sentences name the job by the step it runs too, so a rename of the key alone changes nothing this module checks (the review's
 *  ruling on its third round's finding pins-2 dropped the check that held the key to a name in the sentence: it pinned an
 *  arrangement). Exactly one job runs it; the block's text before that step, with the YAML comment lines removed, is what the
 *  before-Test checks read, so a `#` line naming an engine or a cache is not a step. */
function npmTestJob(ci) {
  const hits = jobBlocks(ci).filter((j) => j.block.includes(NPM_TEST));
  assert.deepEqual(hits.map((j) => j.key).length, 1, 'exactly one job has a step running npm test, so the property below is that job\'s: ' + JSON.stringify(hits.map((j) => j.key)));
  const [job] = hits;
  const before = job.block.slice(0, job.block.indexOf(NPM_TEST)).split('\n').filter((l) => !/^\s*#/.test(l)).join('\n');
  return { key: job.key, before };
}
test('the Tests paragraph\'s premise guard is a test in file-view-seam.test.ts, and the paragraph\'s CI sentence is the PROPERTY of the npm-test job\'s own steps: with the skip sentence, no Playwright install and no browser-cache restore precedes the Test step inside the job that runs npm test (so the legs skip there and the node scene runs); with the run sentence, an install of Firefox and WebKit does', () => {
  const seam = read('ui', 'webview', 'file-view-seam.test.ts');
  assert.ok(seam.includes('\ntest(' + SEAM_GUARD.replace(/"$/, ': ')), 'the seam test holds a test titled by the phrase the section quotes');
  for (const pin of ['Object.keys(MD_PURIFY)', 'RETURN_DOM', 'shadowroot', '\\w+\\(clean\\b', '\\bclean\\.\\w+', 'registerMdPostPass', 'importNode']) assert.ok(seam.includes(pin), 'the guard reads ' + pin);
  // the job's block alone: a Test step in an earlier job, or an install in another job, is not this job's (the round-1 ruling
  // of the fork PR's review, defect B: the pin this replaced counted installs over the whole file and located the Test step by
  // a whole-file offset, so the remedy for the legs' own skip, an install of the engines before npm test, turned it red; that
  // whole-file arrangement, one install after the tests and Chromium alone for the pane bench, is what the file holds today
  // and is not asserted here)
  const ci = read('.github', 'workflows', 'ci.yml');
  const job = npmTestJob(ci);
  const before = job.before;
  // the two step fields a Playwright install and a browser-cache restore are spelled with (the workflow's own steps: `run: npx
  // playwright install <engines>`; `path: ~/.cache/ms-playwright` and `key: playwright-...` under actions/cache), anchored to a
  // line's field so free text names nothing here
  const installBefore = /^\s+run: npx playwright install\b/m.test(before);
  const cacheBefore = /^\s+path: ~\/\.cache\/ms-playwright\s*$/m.test(before) || /^\s+key: playwright-/m.test(before);
  const tests = flat(section().split('**Tests.**')[1] || '');
  const count = (s) => tests.split(s).length - 1;
  const legsSkip = count(CI_SKIP) === 1, legsRun = count(CI_RUN) === 1;
  assert.ok(count(CI_SKIP) + count(CI_RUN) === 1, 'the Tests paragraph carries exactly one of its two CI sentences, once: "' + CI_SKIP + '" or "' + CI_RUN + '" (the paragraph names the other by the constant\'s name, not its text)');
  if (legsSkip) {
    assert.ok(!installBefore && !cacheBefore, 'the plan says the legs skip in CI, but the job that runs npm test (' + job.key + ') installs a Playwright browser or restores its browser cache BEFORE its Test step. If that install is the remedy for the legs\' skip (Firefox and WebKit, or all three engines), reword the Tests paragraph\'s sentence "' + CI_SKIP + '" to "' + CI_RUN + '" in the same commit and this pin holds the job to that install instead; if it is not, move the install after the Test step.');
    // and the legs do skip on that shape: their skip fires when the engine cannot be launched, which no step before npm test changes here
    for (const leg of [LEG, SVG_LEG]) {
      const src = read('ui', 'webview', leg);
      assert.ok(src.includes('t.skip("playwright is not installed under vscode-extension'), leg + ' skips, saying so, without playwright');
      assert.ok(src.includes('t.skip("no playwright " + engine + " on this box'), leg + ' skips, saying so, when an engine cannot be launched');
      assert.ok(src.includes('file-view-figures-gate-adopt.test.ts, the node scene, is the guard that runs where this leg skips'), leg + '\'s skip names the node scene');
    }
  } else {
    const install = /^\s+run: npx playwright install\b([^\n]*)/m.exec(before);
    assert.ok(install, 'the plan says the legs run in CI, so the job that runs npm test (' + job.key + ') installs Playwright\'s engines before its Test step');
    const engines = install[1].trim();
    assert.ok(engines === '' || (/\bfirefox\b/.test(engines) && /\bwebkit\b/.test(engines)), 'the install before the Test step covers Firefox and WebKit (all engines when none is named), the two the legs were red in at the base; it names: ' + JSON.stringify(engines));
  }
  // the scene is a node test: no browser in its name (npm test runs every out-tests file; the legs skip themselves), no Playwright, the
  // shim rule's call, and the roads the section names, by their assertion messages
  const scene = read('ui', 'webview', NODE_SCENE);
  assert.ok(!/(?:require\w*\(|from )["']playwright/.test(scene), 'the scene reaches no browser: no import or require of playwright (its comments may name the legs\' engines)');
  assert.ok(scene.includes('hideEdges(this)'), 'the stand-in is on the shim rule');
  assert.ok(scene.includes('"road (a): no fetching attribute on an unlisted host, none page-relative, on any node at the moment it entered the live document"'), 'road (a), the adoption');
  assert.ok(scene.includes('"road (b): no write of a fetching attribute on an unlisted host, or page-relative, landed on a live-document element"'), 'road (b), the writes');
  // road (a) read tree-wide, ahead of the batch-count pin, and the end state (the review's third round: an img appended into a
  // paragraph after the adoption passed the top-level read and road (b), since its src was written while it was the sanitizer's)
  assert.ok(scene.includes('"road (a): no node that entered the live document anywhere under the Rendered box, at any depth, by any pass, carried a fetching attribute on an unlisted host or page-relative at that moment"'), 'road (a), tree-wide');
  assert.ok(scene.indexOf('intoBoxTree(md).flatMap') < scene.indexOf('every top-level child of the sanitizer'), 'the tree-wide read runs before the batch-count pin, so an order regression names the leak first');
  assert.ok(scene.includes('"the rendered box holds no fetching attribute on an unlisted host and none page-relative"'), 'the end state, the file kind');
  assert.ok(scene.includes('"the rendered box holds no leaking fetching attribute once the render is done"'), 'the end state, the URL kind');
  // the property guard (the round-1 ruling, defect A): the end state through the gate's own oracle, standing on its own per kind
  assert.match(scene, /^import \{[^}]*\bgateRefs\b[^}]*\} from "\.\/figure-gate";/m, 'the scene imports the gate\'s own walk, gateRefs');
  assert.match(scene, /^import \{[^}]*\bunlistedHosts\b[^}]*\} from "\.\/figure-gate";/m, 'and its judge, unlistedHosts');
  assert.match(scene, /^import \{[^}]*\ballowedFigureHosts\b[^}]*\} from "\.\/figure-gate";/m, 'and the set it reads, allowedFigureHosts (the guard judges by the gate\'s set, pinned equal to the scene\'s)');
  assert.ok(scene.includes('assert.deepEqual(unlistedHosts(box, PAGE, allowed), [], "the gate\'s own oracle over the box\'s end state: no fetching attribute under the Rendered box names an unlisted host'), 'and asserts it over the box\'s end state');
  assert.ok(scene.includes('test("the property guard, the file kind:') && scene.includes('test("the property guard, the URL kind:'), 'one property-guard test per kind, standing on its own');
  // the order leg (the round-1 ruling, defect D): the gate's last move-aside before the first move of any body node, over all moves
  assert.ok(scene.includes('road (e), the order: the first move of any node of the sanitizer\'s body into the live document'), 'road (e), the order by the clock');
  assert.ok(scene.includes('loadGatedHost("remote.test", doc as unknown as ParentNode);'), 'the click phase restores through the product\'s own door');
});

test('the stripper\'s readers, derived from the tree: every test module under ui/webview importing ui/test-code-only.ts is named in the guards paragraph\'s five-reader sentence and in the stripper\'s own header, and the count the sentence states is that list\'s length (the round-2 review\'s regression-2 and regression-3: both named three where five imported it)', () => {
  const dir = path.join(REPO, 'ui', 'webview');
  const readers = fs.readdirSync(dir).filter((f) => f.endsWith('.test.ts') && fs.readFileSync(path.join(dir, f), 'utf8').includes('from "../test-code-only"')).sort();
  assert.ok(readers.length >= 5, 'the derivation found the readers (an empty or shrunken list is a broken derivation, not a clean tree): ' + readers.join(', '));
  const guards = flat(section().split("**The guards after the review's first round.**")[1].split('**Scope.**')[0]);
  const m = /(\w+) modules read comment-stripped code \(`grep -l 'from "\.\.\/test-code-only"' ui\/webview\/\*\.test\.ts`: ([^)]*?)(?:, the last two since|\))/.exec(guards);
  assert.ok(m, 'the guards paragraph states the readers with the grep that derives them');
  const words = { three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
  assert.equal(words[m[1].toLowerCase()], readers.length, 'the count the sentence states is the number of modules importing the stripper: ' + readers.join(', '));
  for (const r of readers) assert.ok(m[2].includes(r), 'the guards paragraph names ' + r + ' among the readers');
  const header = read('ui', 'test-code-only.ts').split('\nimport ')[0];
  for (const r of readers) assert.ok(header.includes(r), "the stripper's header names " + r + ' (regression-3: an editor of the stripper reads that header first)');
  assert.ok(header.includes('grep -l \'from "../test-code-only"\' ui/webview/*.test.ts'), "the header states the derivation, so the list is the grep's and not a roster");
});

test('the property guard\'s bound is disclosed in the gate\'s own terms: the tags of figure-gate.ts\'s FIGURE_SEL, read off the source, are each named in the guards paragraph\'s bound sentence and in the node scene\'s header, both of which say the guard answers whether the gate\'s model saw a leak and not whether anything fetched (the round-2 review\'s correctness-3, tests-2, extra6-2)', () => {
  const gate = read('ui', 'webview', 'figure-gate.ts');
  const m = /^export const FIGURE_SEL = "([^"]+)";/m.exec(gate);
  assert.ok(m, 'figure-gate.ts exports FIGURE_SEL as one string literal');
  const tags = m[1].split(',').map((t) => t.trim());
  assert.ok(tags.length >= 7 && tags.every((t) => /^[A-Za-z]+$/.test(t)), 'the selector is a tag list: ' + m[1]);
  const guards = flat(section().split("**The guards after the review's first round.**")[1].split('**Scope.**')[0]);
  const bound = /The guard is keyed on figure-gate's own tag table \(FIGURE_SEL: ([^;]*);/.exec(guards);
  assert.ok(bound, 'the guards paragraph states the bound with the table');
  for (const t of tags) assert.ok(new RegExp('\\b' + t + '\\b').test(bound[1]), 'the bound sentence names ' + t + ' (a tag added to FIGURE_SEL is named here or this is red)');
  assert.ok(guards.includes('answers "did the gate\'s model see a leak", not "did anything fetch"'), 'the paragraph says what the guard answers');
  const header = read('ui', 'webview', NODE_SCENE).split('\nimport ')[0];
  const hb = /gateRefs walks figure-gate's own tag table, FIGURE_SEL, ([^,]*(?:,[^,]*)*?) and (\w+), with the attributes/.exec(prose(header));
  assert.ok(hb, "the scene's header states the bound with the table");
  for (const t of tags) assert.ok(new RegExp('\\b' + t + '\\b').test(hb[1] + ' ' + hb[2]), "the scene's header names " + t);
  assert.ok(prose(header).includes('answers "did the gate\'s model see a leak" and not "did anything fetch"'), 'the header says what the guard answers');
});

